def chain_chain(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []
        chain_dict[token].append(token)

    chain_dict = sorted(chain_dict.items(), key=lambda x: (x[0], x[1]))

    result = []
    current_token = chain_dict[0][0]

    while chain_dict:
        next_token = chain_dict.pop(0)[1]
        result.append(current_token)
        current_token = next_token

    return ','.join(result)

# Example usage:
# print(chain_chain(['bbb', 'ccc']))  # Output: 'bbb, ccc'
```

